cat > /tmp/patch.py <<'EOF'
EOF
python3 - <<'EOF'
p='src/services/order-service.js'
s=open(p).read()
s=s.replace("import { query } from '../db.js';\n","import { query } from '../db.js';\nimport { OrderRepository } from '../repositories/order-repository.js';\n",1)
s+="""
export async function totalPaidCentsByUser(repo = new OrderRepository()) {
  const rows = await repo.findPaid();
  const totals = {};
  for (const o of rows) {
    totals[o.user_id] = (totals[o.user_id] ?? 0) + o.total_cents;
  }
  return totals;
}
"""
open(p,'w').write(s)
t='tests/order-service.test.js'
s=open(t).read()
s=s.replace("import { listOrdersForUser, totalPaidCents } from","import { listOrdersForUser, totalPaidCents, totalPaidCentsByUser } from")
s+="""
test('totalPaidCentsByUser sums paid orders per user', async () => {
  const totals = await totalPaidCentsByUser();
  assert.deepEqual(totals, { 1: 4200, 2: 9900, 3: 500 });
});

test('totalPaidCentsByUser accumulates multiple orders for one user', async () => {
  const repo = {
    findPaid: async () => [
      { user_id: 7, total_cents: 100 },
      { user_id: 7, total_cents: 250 },
      { user_id: 8, total_cents: 40 },
    ],
  };
  assert.deepEqual(await totalPaidCentsByUser(repo), { 7: 350, 8: 40 });
});
"""
open(t,'w').write(s)
EOF
npm test 2>&1 | tail -15

